<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { accionOrden, detalleOrden, guardarOrden, imprimirOrden, listarOrdenes, prepararOrden, type Orden, type OrdenLinea, type OrdenOptions, type TipoOrden } from '../services/ordenes'
const type=ref<TipoOrden>('compra'),rows=ref<Orden[]>([]),options=ref<OrdenOptions>({proveedores:[],estados:[],procesos:[]}),total=ref(0),lastPage=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),detail=ref<Orden|null>(null),editing=ref<number|null>(null),processId=ref(0)
const filters=reactive({date_from:'',date_to:'',proveedor_id:'',estado:'',id:'',page:1}),form=reactive({proceso_id:0,proveedor:'',ruc:'',moneda_id:0,observacion_orden:'',otros_conceptos:0,forma_pago:'',forma_entrega:'',plazo_entrega:'',validez_oferta:'',items:[] as OrdenLinea[]})
const itemsTotal=computed(()=>form.items.reduce((sum,x)=>sum+(Number(x.cantidad)||0)*(Number(x.precio)||0),0)),subtotal=computed(()=>itemsTotal.value/1.18),igv=computed(()=>itemsTotal.value-subtotal.value),grandTotal=computed(()=>itemsTotal.value+(Number(form.otros_conceptos)||0)),currency=computed(()=>form.moneda_id===0?'S/':'$')
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const response=await listarOrdenes(type.value,filters);rows.value=response.data;total.value=response.total;lastPage.value=response.last_page;options.value=response.options}catch(cause){error.value=message(cause)}finally{loading.value=false}}
async function create(){if(!processId.value){error.value='Seleccione un proceso adjudicado.';return}loading.value=true;try{const draft=await prepararOrden(processId.value,type.value);fill(draft);editing.value=null;modal.value=true}catch(cause){error.value=message(cause)}finally{loading.value=false}}
async function edit(item:Orden){try{const current=await detalleOrden(item.id);fill(current);editing.value=item.id;modal.value=true}catch(cause){error.value=message(cause)}}
function fill(order:Orden){Object.assign(form,{proceso_id:order.proceso_id,proveedor:order.proveedor,ruc:order.ruc,moneda_id:order.moneda_id,observacion_orden:order.observacion||'',otros_conceptos:order.otros_conceptos||0,forma_pago:order.forma_pago||'',forma_entrega:order.forma_entrega||'',plazo_entrega:order.plazo_entrega||'',validez_oferta:order.validez_oferta||'',items:order.detalles?.map(x=>({...x}))||[]})}
async function save(){if(!form.proceso_id||!form.items.length){error.value='La orden debe estar vinculada a un proceso y contener ítems.';return}if(form.items.some(x=>x.cantidad<=0||x.precio<0)){error.value='Revise cantidades y precios.';return}saving.value=true;try{await guardarOrden(editing.value,{...form,tipo:type.value,subtotal:subtotal.value,igv:igv.value,total:itemsTotal.value,items_json:form.items.map(x=>({...x,valor:x.cantidad*x.precio}))});success.value='Orden guardada correctamente.';modal.value=false;await load()}catch(cause){error.value=message(cause)}finally{saving.value=false}}
async function show(item:Orden){try{detail.value=await detalleOrden(item.id)}catch(cause){error.value=message(cause)}}
async function action(item:Orden,value:'notificar'|'anular'){if(!confirm(`¿${value} la orden #${item.id}?`))return;try{await accionOrden(item.id,value);success.value=value==='notificar'?'Orden notificada al proveedor.':'Orden anulada correctamente.';detail.value=null;await load()}catch(cause){error.value=message(cause)}}
function money(value:number,moneda=0){return `${moneda===0?'S/':'$'} ${Number(value||0).toFixed(2)}`}function message(cause:unknown){return cause instanceof Error?cause.message:'No se pudo completar la operación.'}watch(type,()=>load());onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Logística / Órdenes</nav><header class="hero"><div class="mark">OR</div><div><small>MIA · Logística</small><h1>Órdenes de compra y servicio</h1><p>Genera órdenes desde procesos adjudicados y controla su notificación y atención.</p></div><strong>{{total}} órdenes</strong></header><div class="tabs"><button :class="{active:type==='compra'}" @click="type='compra'">Órdenes de compra</button><button :class="{active:type==='servicio'}" @click="type='servicio'">Órdenes de servicio</button></div><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="create"><select v-model="processId"><option :value="0">Seleccione un proceso adjudicado</option><option v-for="process in options.procesos.filter(x=>x.tipo===type)" :key="process.id" :value="process.id">#{{process.id}} · {{process.nombre}}</option></select><button @click="create">+ Generar orden</button></section><section class="filters"><label>Desde<input v-model="filters.date_from" type="date"></label><label>Hasta<input v-model="filters.date_to" type="date"></label><label>Proveedor<select v-model="filters.proveedor_id"><option value="">Todos</option><option v-for="provider in options.proveedores" :key="provider.id" :value="provider.id">{{provider.nombre}}</option></select></label><label>Estado<select v-model="filters.estado"><option value="">Todos</option><option v-for="state in options.estados" :key="state.value" :value="state.value">{{state.label}}</option></select></label><label>ID<input v-model.trim="filters.id"></label><button @click="load(1)">Buscar</button></section><div v-if="loading" class="empty">Cargando órdenes…</div><div v-else-if="!rows.length" class="empty">No existen órdenes de {{type}}.</div><section v-else class="table"><header><span>Orden</span><span>Emisión</span><span>Proveedor</span><span>Subtotal</span><span>IGV</span><span>Total</span><span>Estado</span><span>Acciones</span></header><article v-for="item in rows" :key="item.id"><b>#{{String(item.correlativo||item.id).padStart(5,'0')}}</b><time>{{item.fecha_emision}}</time><div><b>{{item.proveedor}}</b><small>{{item.ruc}}</small></div><span>{{money(item.subtotal,item.moneda_id)}}</span><span>{{money(item.igv,item.moneda_id)}}</span><b>{{money(item.total+item.otros_conceptos,item.moneda_id)}}</b><em>{{item.estado_label}}<small v-if="item.proveedor_notificado">Notificado</small></em><footer><button @click="show(item)">Ver</button><button @click="imprimirOrden(item.id)">Imprimir</button><button v-if="item.puede_editar" @click="edit(item)">Editar</button><button v-if="item.puede_notificar" class="good" @click="action(item,'notificar')">Notificar</button><button v-if="item.puede_anular" class="bad" @click="action(item,'anular')">Anular</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal wide" @submit.prevent="save"><header><div><small>Orden de {{type}}</small><h2>{{editing?'Editar':'Generar'}} orden</h2></div><button type="button" @click="modal=false">×</button></header><section class="supplier"><div><span>Proveedor adjudicado</span><b>{{form.proveedor}}</b></div><div><span>RUC</span><b>{{form.ruc}}</b></div><div><span>Proceso</span><b>#{{form.proceso_id}}</b></div></section><div class="grid"><label>Moneda<select v-model="form.moneda_id"><option :value="0">Soles</option><option :value="2">Dólares</option></select></label><label>Otros conceptos<input v-model.number="form.otros_conceptos" type="number" min="0" step="0.01"></label><label>Forma de pago<input v-model.trim="form.forma_pago"></label><label>Forma de entrega<input v-model.trim="form.forma_entrega"></label><label>Plazo de entrega<input v-model.trim="form.plazo_entrega"></label><label>Validez de oferta<input v-model.trim="form.validez_oferta"></label></div><label>Observaciones<textarea v-model.trim="form.observacion_orden" rows="3"/></label><h3>Detalle adjudicado</h3><div class="lines"><header><span>Ítem</span><span>Cantidad</span><span>Unidad</span><span>Precio unitario</span><span>Valor</span></header><article v-for="line in form.items" :key="line.codigo"><div><b>{{line.denominacion}}</b><small>{{line.glosa}}</small></div><input v-model.number="line.cantidad" type="number" min="0" step="0.01"><span>{{line.unidad}}</span><input v-model.number="line.precio" type="number" min="0" step="0.01"><b>{{currency}} {{(line.cantidad*line.precio).toFixed(2)}}</b></article></div><section class="totals"><div><span>Subtotal</span><b>{{currency}} {{subtotal.toFixed(2)}}</b></div><div><span>IGV</span><b>{{currency}} {{igv.toFixed(2)}}</b></div><div><span>Otros</span><b>{{currency}} {{Number(form.otros_conceptos).toFixed(2)}}</b></div><div class="grand"><span>Total</span><b>{{currency}} {{grandTotal.toFixed(2)}}</b></div></section><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar orden'}}</button></footer></form></div>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal wide"><header><div><small>Orden #{{detail.id}}</small><h2>{{detail.proveedor}}</h2><p>{{detail.estado_label}} · {{detail.proveedor_notificado?'Proveedor notificado':'Pendiente de notificación'}}</p></div><button @click="detail=null">×</button></header><section class="supplier"><div><span>Pedido</span><b>#{{detail.pedido_id}}</b></div><div><span>Proceso</span><b>#{{detail.proceso_id}}</b></div><div><span>Total</span><b>{{money(detail.total+detail.otros_conceptos,detail.moneda_id)}}</b></div></section><h3>Detalle de orden</h3><div class="lines compact"><article v-for="line in detail.detalles" :key="line.codigo"><div><b>{{line.denominacion}}</b><small>{{line.glosa}}</small></div><span>{{line.cantidad}} {{line.unidad}}</span><span>Atendido: {{line.atendido||0}}</span><span>{{money(line.precio,detail.moneda_id)}}</span><b>{{money(line.valor,detail.moneda_id)}}</b></article></div><h3>Atenciones</h3><div class="attention"><div v-for="entry in detail.seguimiento?.atenciones" :key="entry.id"><b>{{entry.item}}</b><span>{{entry.tipo}} · {{entry.cantidad}} · {{entry.fecha}}</span><small>{{entry.usuario}}</small></div><p v-if="!detail.seguimiento?.atenciones.length">Sin atenciones registradas.</p></div><footer class="actions"><button class="clear" @click="detail=null">Cerrar</button><button @click="imprimirOrden(detail.id)">Imprimir</button><button v-if="detail.puede_notificar" class="good-bg" @click="action(detail,'notificar')">Notificar proveedor</button><button v-if="detail.puede_anular" class="bad-bg" @click="action(detail,'anular')">Anular orden</button></footer></section></div></div></template>
<style scoped>
